import{_ as a,o as t,c as o,a3 as n}from"./chunks/framework.DAK02U1-.js";const f=JSON.parse('{"title":"Refactor","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Refactor | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/cli/refactor"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/cli/refactor"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/refactor"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/refactor"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/refactor"}]]},"headers":[],"relativePath":"clice/cli/refactor.md","filePath":"en/clice/cli/refactor.md","lastUpdated":1791156255000}'),r={name:"clice/cli/refactor.md"};function i(s,e,c,l,d,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="refactor" tabindex="-1">Refactor <a class="header-anchor" href="#refactor" aria-label="Permalink to &quot;Refactor&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>clice refactor</code> rewrites the workspace&#39;s sources from the persisted index, the same index <code>clice query</code> reads. Nothing is compiled, so a refactoring over a large tree takes about as long as a query. <code>rename</code> is the one refactoring today; an editor&#39;s rename runs the same engine.</p><p><strong>Usage</strong>: <code>clice refactor rename --to &lt;name&gt; (--name &lt;query&gt; | --symbol &lt;id&gt; | --path &lt;file&gt; --line &lt;n&gt;) [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] [--dry-run] [--fresh]</code></p><h2 id="rename" tabindex="-1">Rename <a class="header-anchor" href="#rename" aria-label="Permalink to &quot;Rename&quot;">​</a></h2><p>The symbol is named as <code>clice query</code> names one: by a <a href="./query#name-queries">name query</a>, by the <code>#&lt;hex&gt;</code> id an earlier answer carried, or by the file and line defining it. A name several symbols spell lists them and asks for an id.</p><p>A rename changes every declaration, definition and reference the index ties to the symbol, and the symbols that must keep its name:</p><ul><li>a class&#39;s constructors and destructor — renaming a constructor renames its class;</li><li>the explicit and partial specializations of a template, and the deduction guides of a class template;</li><li>the overrides a virtual function is linked with, in base and derived classes.</li></ul><p>Operators, conversion functions, user-defined literals, macros, symbols declared in system headers and symbols whose every declaration a macro spells cannot be renamed. The new name must be an identifier that is a keyword in neither C nor C++; a name reserved for the implementation (<code>__x</code>, <code>_X</code>, and <code>_x</code> at global scope) is a warning.</p><h2 id="answers" tabindex="-1">Answers <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;Answers&quot;">​</a></h2><p>The answer is one JSON object, <code>{&quot;result&quot;: ..., &quot;stale&quot;: [...]}</code>, like a query&#39;s:</p><ul><li><code>files</code> lists the tokens replaced in each file, with a 1-based line and byte column. <code>heuristic</code> marks one reached through a name the index resolved by heuristics — a call in a template whose callee depends on a template parameter — worth a look.</li><li><code>unconfirmed</code> lists the places spelling the old name that the rename leaves alone because the index cannot say what they name: the body of a <code>#define</code>, a macro whose expansion spells the name, an inactive <code>#if</code> branch, a file no unit of the build compiles, a token that also names another symbol of the old name — under another build configuration, or as another overload a call in a template may pick. Read them before building.</li><li><code>warnings</code> are made anyway: the new name overloads a function of the same scope, hides or collides with a local of the same function, or is declared in a function using the renamed name, where it would capture that use.</li><li><code>conflicts</code> stop the rename: the new name is declared in the same scope already, is a macro, names a parameter or label of the same function, a member of a base or derived class, the class the renamed member belongs to or a member of the renamed class; the rename would edit a file outside the workspace; two namespaces would merge.</li><li><code>stale</code> lists the files the rename edits, or that spell the old or the new name, whose indexed rows are not current — changed since they were indexed, or never indexed while some unit of the build still is not. They stop the rename as well; <code>--fresh</code> reindexes them first.</li></ul><p>The exit code is 0 when the rename was written, or planned under <code>--dry-run</code>, and 1 when a conflict or a stale file stopped it or the symbol cannot be renamed — with <code>{&quot;error&quot;: &quot;...&quot;}</code> saying why in the last case. Arguments that do not parse exit with 2.</p><h2 id="writing" tabindex="-1">Writing <a class="header-anchor" href="#writing" aria-label="Permalink to &quot;Writing&quot;">​</a></h2><p>Without <code>--dry-run</code> the command writes the files once every new text is computed: a file whose text changed since the plan was made stops the whole rename before anything is written. Each file is rewritten in place, keeping its byte order mark, line endings and permissions; a file that cannot be written — read-only, or a full disk — stops the rename there, and the error names the files already rewritten.</p><p>Only the workspace is edited: hidden directories, the cache directory and build trees (a directory holding <code>CMakeCache.txt</code> or <code>build.ninja</code>) are left out. Its sources and headers are searched for the two names by suffix; an edit the index places may land in a file of any suffix.</p><p>The command reads the disk; unsaved editor buffers are invisible to it. Save them first, or rename from the editor.</p><h2 id="in-the-editor" tabindex="-1">In the editor <a class="header-anchor" href="#in-the-editor" aria-label="Permalink to &quot;In the editor&quot;">​</a></h2><p>The editor&#39;s rename selects the name under the cursor, or says why the symbol there cannot be renamed. The edits it returns are versioned against the open buffers, which it reads instead of the disk. Conflicts and stale files answer an error naming them; warnings, the places left alone and the edits made through heuristics are shown in a message.</p><h2 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h2><ul><li>The checks are static: a change of meaning the index cannot see — argument-dependent lookup finding another function, a member of the new name capturing a use inside its class, an overload that cannot coexist with the renamed function — goes unnoticed. Build after renaming.</li><li>Macros cannot be renamed yet.</li><li>An editor&#39;s rename edits through the index of the project serving the file; another project open in the same editor keeps its uses of the symbol.</li></ul>',21)])])}const u=a(r,[["render",i]]);export{f as __pageData,u as default};
